import React, { useState, useEffect } from "react";
import axios from "axios";

function WaiterDashboard() {
  const [orders, setOrders] = useState([]);

  // Load orders when page opens
  useEffect(() => {
    refreshOrders();

    // Optional: Real-time updates using polling every 5s
    const interval = setInterval(refreshOrders, 5000);
    return () => clearInterval(interval);
  }, []);

  const refreshOrders = () => {
    axios.get("http://localhost:5000/api/orders")
      .then(res => setOrders(res.data))
      .catch(err => console.error("Error fetching orders:", err));
  };

  // Update order status (e.g., waiter sends to kitchen)
  const updateStatus = (orderId, status) => {
    axios.put(`http://localhost:5000/api/orders/${orderId}/status`, { status })
      .then(() => {
        alert(`Order ${orderId} updated to ${status}`);
        refreshOrders();
      })
      .catch(err => alert("Error updating status: " + err.message));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Waiter Dashboard</h2>

      {orders.length === 0 ? (
        <p>No active orders.</p>
      ) : (
        <ul>
          {orders.map(order => (
            <li key={order.id} style={{ marginBottom: "15px" }}>
              <strong>Table {order.table_number}</strong> — Status: {order.status} — Chef: {order.chef_id || "Unassigned"}
              <div style={{ marginTop: "5px" }}>
                {order.status === "Received" && (
                  <button onClick={() => updateStatus(order.id, "Preparing")}>
                    Send to Kitchen
                  </button>
                )}
                {order.status === "Ready" && (
                  <button onClick={() => updateStatus(order.id, "Paid")}>
                    Mark as Served
                  </button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default WaiterDashboard;
